// Прод, только чтение: сырой HTML через request API, гость.
import { test, expect } from '@playwright/test';
import { rawHtml, rootHtml, metas } from './ssr-seo.helpers';

const PRIVATE = ['/messages', '/addbusiness', '/mybusinesses', '/userprofile'];

test.describe('SSR и SEO публичных страниц — SSR-контент', () => {
  test('Приватные страницы: #root в сыром HTML пустой, meta robots noindex #b3dc2e @desktop @prod-safe', async ({ request }) => {
    for (const url of PRIVATE) {
      await test.step(url, async () => {
        const { status, html } = await rawHtml(request, url);
        expect(status, url).toBe(200);
        const root = rootHtml(html);
        expect(root, `${url}: есть #root`).not.toBeUndefined();
        expect(root!.trim(), `${url}: #root пустой`).toBe('');
        expect(html, `${url}: нет SSR-блока`).not.toContain('data-seo-body');
        const robots = metas(html, 'robots');
        expect(robots.length, `${url}: meta robots`).toBeGreaterThan(0);
        expect(robots.join(','), `${url}: noindex`).toMatch(/noindex/i);
      });
    }
  });
});
